"""Export reviewed generated bytes from a verified Fern download."""
from __future__ import annotations

import hashlib
import io
import json
import re
from pathlib import Path
import subprocess
import tarfile

from attestation import parse_json
from common import (GENERATED_DATA_FILES, GENERATED_GO_PATH, PipelineError, canonical,
                    clean_env, module_rewrite, protected, require, safe_path, sha256, version_tuple)
import fern_provenance
from harden_wire_tests import COMPOSE_RAW, COMPOSE_HARDENED

RECEIPT_PATH = ".fern/provenance.json"
GENERATED_NONPUBLIC = {"README.md", "CONTRIBUTING.md", "wiremock/docker-compose.test.yml", RECEIPT_PATH}
EXCLUDED_PREFIXES = ("legacy/", "scripts/", ".github/", ".circleci/", ".sdk-release/")


def literal_ignores(data: bytes) -> tuple[str, ...]:
    """Only reviewed literal file/directory entries can decide what is maintained."""
    result = []
    for line in data.decode("utf-8").splitlines():
        name = line.strip()
        if not name or name.startswith("#"):
            continue
        require(not any(char in name for char in "*?![]\\"), "Unsupported SDK preservation pattern")
        safe_path(name.removesuffix("/"))
        result.append(name)
    return tuple(result)


def ignored(name: str, patterns: tuple[str, ...]) -> bool:
    return any(name == item or item.endswith("/") and name.startswith(item) for item in patterns)


def maintained(name: str, patterns: tuple[str, ...]) -> bool:
    return (name == ".fernignore" or protected(name) or name.startswith(EXCLUDED_PREFIXES)
            or ignored(name, patterns))


def generated_path(name: str) -> bool:
    return not name.startswith(EXCLUDED_PREFIXES) and bool(name in GENERATED_DATA_FILES or GENERATED_GO_PATH.fullmatch(name))


def git_files(repo: Path, commit: str) -> dict[str, tuple[str, bytes]]:
    """Read and hash blob bytes without checking out or executing repository files."""
    tree = subprocess.run(["git", "ls-tree", "--full-tree", "-rz", commit], cwd=repo,
        env=clean_env(GIT_NO_REPLACE_OBJECTS="1", GIT_NO_LAZY_FETCH="1"), capture_output=True, timeout=60)
    require(tree.returncode == 0, "Could not read the public SDK base tree")
    records = tree.stdout
    entries = {}
    for record in records.split(b"\0"):
        if not record:
            continue
        meta, raw_name = record.split(b"\t", 1)
        mode, kind, oid = meta.decode().split()
        name = safe_path(raw_name.decode("utf-8"))
        require(name not in entries and kind == "blob" and mode in {"100644", "100755"}, "Unsafe raw SDK tree entry")
        require(len(oid) == 40 and all(char in "0123456789abcdef" for char in oid), "Invalid raw SDK object")
        entries[name] = (mode, oid)
    require(0 < len(entries) <= 20000, "Raw SDK exceeds the file-count limit")
    identifiers = list(dict.fromkeys(oid for _, oid in entries.values()))
    result = subprocess.run(["git", "cat-file", "--batch"], cwd=repo,
        env=clean_env(GIT_NO_REPLACE_OBJECTS="1", GIT_NO_LAZY_FETCH="1"),
        input=("\n".join(identifiers) + "\n").encode(), capture_output=True, timeout=180)
    require(result.returncode == 0 and len(result.stdout) <= 1024 * 1024 * 1024, "Could not read bounded raw SDK blobs")
    blobs, position, total = {}, 0, 0
    for oid in identifiers:
        end = result.stdout.index(b"\n", position)
        actual, kind, size = result.stdout[position:end].split()
        size = int(size)
        require(actual.decode() == oid and kind == b"blob" and 0 <= size <= 100 * 1024 * 1024, "Unexpected raw SDK blob")
        data = result.stdout[end + 1:end + 1 + size]
        require(len(data) == size and result.stdout[end + 1 + size:end + 2 + size] == b"\n", "Truncated raw SDK blob")
        require(hashlib.sha1(b"blob " + str(size).encode() + b"\0" + data).hexdigest() == oid, "Raw SDK blob bytes differ from the signed tree")
        total += size
        require(total <= 1024 * 1024 * 1024, "Raw SDK exceeds the byte limit")
        blobs[oid] = data
        position = end + size + 2
    require(position == len(result.stdout), "Unexpected trailing raw SDK object bytes")
    return {name: (mode, blobs[oid]) for name, (mode, oid) in entries.items()}


def _export(directory, expected_tree, public_files, version, settings, output, forbidden_values):
    from generate import CALLER_HOOK

    current = fern_provenance.read_download_files(directory)
    require(fern_provenance.download_tree(current) == expected_tree, "Downloaded SDK changed after verification")
    require(RECEIPT_PATH in current, "Downloaded SDK receipt is missing")
    public_patterns = literal_ignores(public_files[".fernignore"][1])
    previous = re.fullmatch(rb"module github\.com/plaid/plaid-go/v([1-9][0-9]*)", public_files["go.mod"][1].splitlines()[0])
    require(previous is not None, "Unexpected public SDK base module")
    before, after = int(previous[1]), version_tuple(version)[0]
    require(after in {before, before + 1}, "Unexpected generated SDK major transition")
    caller = public_files["internal/caller.go"][1]
    require(caller.count(CALLER_HOOK.encode()) == 1, "Public caller is missing its reviewed destination guard")
    caller = module_rewrite(caller, before, after).replace(CALLER_HOOK.encode(), b"", 1)
    require(current.get("internal/caller.go") == caller, "Fresh Fern caller differs from the reviewed public runtime")
    require(maintained("internal/caller.go", public_patterns), "Public runtime must remain maintained")
    selected = {}
    for name, data in current.items():
        require(generated_path(name) or name in GENERATED_NONPUBLIC, "Unexpected file in fresh SDK download")
        if name == "wiremock/docker-compose.test.yml":
            require(data in {COMPOSE_RAW.encode(), COMPOSE_HARDENED.encode()}, "Unexpected generated mock-server configuration")
        if name in GENERATED_NONPUBLIC or maintained(name, public_patterns):
            continue
        if name == ".fern/metadata.json":
            metadata = parse_json(data)
            expected = {"cliVersion": settings["cli_version"], "generatorName": settings["generator_image"],
                        "generatorVersion": settings["generator_version"], "sdkVersion": "v" + version}
            require(all(metadata.get(key) == value for key, value in expected.items()), "Raw Fern metadata differs from generation settings")
            config = metadata.get("generatorConfig", {})
            module = "github.com/plaid/plaid-go/v" + version.split(".")[0]
            require(config.get("module", {}).get("path") == module and config.get("importPath") == module
                    and type(config.get("maxRetries")) is int and config["maxRetries"] == 0,
                    "Raw Fern metadata differs from the public module or retry policy")
            data = (json.dumps(expected, indent=2) + "\n").encode()
        require(re.search(rb"\bgithub\.(?!com\b|io\b|blog\b|dev\b)[a-z0-9.-]+", data, re.I) is None,
                "Generated SDK contains a private repository reference")
        require(all(not value or value not in data for value in forbidden_values), "Generated SDK contains a privileged credential")
        selected[name] = data
    require(".fern/metadata.json" in selected and any(name.endswith(".go") for name in selected), "Hosted SDK output is incomplete")
    require(not any(output.iterdir()), "Hosted output directory must be empty")
    index = canonical([[name, "100644", sha256(data)] for name, data in sorted(selected.items())])
    (output / "fern-content.json").write_bytes(index)
    with tarfile.open(output / "fern-output.tar.gz", "w:gz") as archive:
        for name, data in sorted(selected.items()):
            entry = tarfile.TarInfo(name)
            entry.mode, entry.size = 0o644, len(data)
            archive.addfile(entry, io.BytesIO(data))
    return sha256(index)


def export_verified_output(*, directory: Path, expected_tree: str, public_files: dict[str, tuple[str, bytes]],
                           version: str, settings: dict, output: Path,
                           forbidden_values: tuple[bytes, ...] = ()) -> str:
    """Caller must verify Fern's original receipt before entering this boundary."""
    try:
        return _export(directory, expected_tree, public_files, version, settings, output, forbidden_values)
    except Exception:
        # Git/path/parser exceptions can contain private data; never expose them.
        raise PipelineError("Verified Fern output failed the public export policy") from None
